/*
 * 异空间 · 酒馆助手脚本版 v1.6.18
 * 本版改动（1.6.18：修复手机端退出小剧场三选项确认框偏向屏幕底部的问题，改为相对视口居中并限制在动态视口内滚动。1.6.17：新增正文浮标样式选择，默认胶囊、可切换仅星星；支持拖到屏幕左右边缘收起并向内拖出，样式和停靠位置跨重载保存。1.6.16：预览结束后自动返回“美化与位置”设置页；小剧场横幅、氛围与其他装饰 CSS 管理器统一文件选择、编辑、应用、新增和预览流程；无 CSS 文件时显示全宽虚线新增按钮。1.6.15：夜间主题的区域顶部强调线改为淡紫色，并明确排除会显示酒馆聊天文件的正文聊天页；1.6.14：异空间除正文聊天页外的实线区域框顶部加粗并按日夜主题着色，虚线说明框保持原样；1.6.13：新增酒馆聊天预设读取与小剧场专属预设切换，进场切换、退场恢复；1.6.12：从 v1.6.11 基线重做横幅四模式与自定义 CSS 管理，并加入独立的小剧场氛围 CSS、其他装饰 CSS；正文聊天区改为显示区唯一主线文件+按文件大小排序的隐藏区，支持移入显示区、逐文件锁定及可选前10条显示；1.6.1：浮标单击进入异空间/双击退出小剧场、给酒馆页面加 data-xsh-stage 属性供美化显示小剧场名；1.6.0：不再手动保存聊天文件（修复400）、新开聊天进入小剧场、按文件大小排序与固定显示、退出回到进入前的正文；1.5.7：小字改浅色、标题栏日夜切换按钮、自带日间配色；1.5.6：弹窗强制不透明、遮罩加深；1.5.5：弹窗/面板自动对比度，修复跟随酒馆美化时文字看不清；1.5.4：描述改称描述、搜索框、默认跟随酒馆美化；1.5.3：提示在面板内显示、保存后自动返回、日夜美化、双态浮标、默认菜单图标；1.5.2：美化区/氛围滤镜/自动切换酒馆美化/图标可放菜单/面板强制不透明覆盖）：
 *  1) 修复 AI 生成小剧场预览区被横向排列的问题，并新增“返回”按钮；
 *  2) 小剧场记忆总结可选读取来源（当前聊天/任一聊天文件）与楼层范围（全部/最近N条/指定楼层）；
 *  3) AI 生成小剧场可选是否读取 user 人设、char 人设、世界书（精确到每个条目）；
 *  4) 正文聊天支持从异空间列表“移除”聊天文件（酒馆原生文件保留，可恢复）；
 *  5) 世界观描述字数改为 20-1000；新增可编辑的内置“小剧场演绎规则”提示词（高权重注入）；
 *  6) 设置页拆分为“提示词/接口与其它”两页；提示词统一在右上角保存，CSS 自定义区保留独立保存；
 *  7) 记忆互通的可编辑文本框增加展开/收起；
 *  8) 小剧场与正文聊天文件互斥（小剧场进行中不能切换正文聊天文件）；
 *  9) 切换聊天加载提速：先关面板再加载，自动取标题延后并精简；
 * 10) 点击浮标默认进入“小剧场”列表，顶部直接显示“退出小剧场”；
 * 11) 新增“小剧场存档”：退出小剧场自动保存聊天文件、清空酒馆聊天、后台只取标题+描述并记录日期时间，可进入/移除。
 * 12) 正文聊天编辑标题并保存时，同步重命名酒馆原生聊天文件；核验成功后迁移异空间索引。
 * 13) 异空间设置面板细节美化：说明虚线框、暗色黄虚线、搜索按钮与省略号、折叠箭头、小剧场入口尺寸统一；提示词和外观设置统一保存，装饰仅作用于异空间面板。
 * 14) 按用户反馈微调折叠箭头、夜间星点底纹与小字虚线范围，并改善移动端键盘下搜索框可见性。
 */
(() => {
  'use strict';
  const KEY_STAGES='异空间.小剧场.v1', KEY_SETTINGS='异空间.模型设置.v1';
  const cssId='xspace-helper-style', rootId='xspace-helper-root', iconId='xspace-helper-icon';
  const host=window.parent, doc=host.document;
  const $=(s,r=doc)=>r.querySelector(s), $$=(s,r=doc)=>r.querySelectorAll(s);
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const toast=(s,duration=3400)=>{console.info('[异空间]',s);try{addStyle();let box=$('#xsh-toast-box');if(!box){box=doc.createElement('div');box.id='xsh-toast-box';}doc.body.append(box);const t=doc.createElement('div');t.className='xsh-toast';t.textContent=String(s);box.append(t);setTimeout(()=>t.remove(),duration);}catch{}};
  const readJson=(k,d)=>{try{return JSON.parse(localStorage.getItem(k)||JSON.stringify(d));}catch{return d;}};
  const readStages=()=>readJson(KEY_STAGES,[]), writeStages=x=>{localStorage.setItem(KEY_STAGES,JSON.stringify(x));try{applyInjection();}catch{}};
  const MIN_DESC=20,MAX_DESC=1000;
  const DEF={
    memoryPrompt:'请按时间顺序总结关键事件、人物关系、情绪变化、重要伏笔和当前状态，不要编造。',
    stagePrompt:'请根据用户的创意，设计一个适合沉浸式角色扮演的小剧场世界观。设定具体、有氛围、便于持续互动，并给出可以展开的开场情境。',
    titlePrompt:'请阅读以下聊天记录，为这段聊天取一个标题和一段描述。只输出两行：第一行是标题（不超过12个字，不要引号和标点）；第二行是描述（不超过40个字，让人一眼看出大概聊了什么、聊到了哪）。不要输出其他任何内容，不要写成长篇概括。',
    stageRulePrompt:[
      '【异空间·小剧场演绎规则｜最高优先级】',
      '当前正在进行“小剧场”演绎。小剧场设定及其中已发生的剧情，优先级高于角色卡、世界书、预设以及此前聊天中与之冲突的任何内容。',
      '',
      '1. 以小剧场为准：角色的身份、种族、形态、职业、年龄、处境、能力、人际关系、所在地点和当前状态，一律以小剧场设定与已发生的剧情为准，覆盖角色卡里的原始设定。',
      '2. 人格不变，身份可变：角色的性格、说话习惯、价值观和情感倾向保持一致；但身份和状态可以被彻底改变，并且必须贯彻到底。例如小剧场写他今生变成了一头猪，他就是一头猪——以猪的身体、感官、体型、行动能力和社会处境行事，性格仍是他的性格，不能再做猪做不到的事。',
      '3. 形态决定行为与交流方式：变成鬼魂、动物、物件、婴儿、失忆、重伤、被囚禁等状态后，其行动、感知和沟通方式必须符合新状态与世界规则。例如变成鬼魂后，若设定中活人看不见、听不见他，就不能像生前一样与 user 正常对话，只能通过设定允许的方式（异象、梦境、附身、特殊媒介等）互动；动物不能说人话，除非设定明确允许。',
      '4. 不要无故复原：除非剧情明确推动，否则不要让身份、形态、状态自行恢复成角色卡里的“原样”，也不要用角色卡里已被小剧场推翻的设定来写作。',
      '5. 信息边界：角色只知道其当前身份能感知、能知道的信息，不得越界知晓 user 的内心活动或自己看不到的事。',
      '6. 尊重 user：不替 user 说话、做决定或描写其内心活动；保持小剧场的世界观、文风与节奏一致。',
      '',
      '【输出前自检（在心里完成，不要把自检过程写出来）】',
      '① 角色当前的身份、形态、状态是什么？与小剧场设定是否一致？',
      '② 我写的台词和动作，以这个身份此刻真的做得到吗？对方听得见、看得懂吗？',
      '③ 有没有沿用角色卡里已被小剧场推翻的设定？',
      '④ 角色的性格与说话方式是否保持？',
      '⑤ 有没有替 user 说话或行动？',
      '任何一项不通过，先修改再输出。'
    ].join('\n')
  };
  const readSettings=()=>Object.assign({mode:'tavern',source:'openai',apiurl:'',key:'',model:'',memoryPrompt:DEF.memoryPrompt,stagePrompt:DEF.stagePrompt,titlePrompt:DEF.titlePrompt,stageRulePrompt:DEF.stageRulePrompt,stageRuleOn:true,stagePresetOn:false,stagePresetName:'',stagePresetSession:null,stageApiMode:'shared',stageSource:'openai',stageApiurl:'',stageKey:'',stageModel:'',stageCtx:{persona:true,char:true,entries:{}},ownTheme:false,skinMode:'builtin',skinCustom:'',atmCustomCss:'',atmCustomCssFiles:[],atmCustomCssActiveId:'',atmCustomCssOn:null,stageDecorCss:'',stageDecorCssFiles:[],stageDecorCssActiveId:'',stageDecorOn:false,ownMode:'night',iconPos:'menu',floatIdle:true,floatStyle:'capsule',chatHiddenShowTen:false,atm:{on:false,preset:'mist',level:60,border:'dual',anim:true},themeSwitch:{on:false,day:['',''],night:['',''],dayFrom:6,nightFrom:18}},readJson(KEY_SETTINGS,{}));
  const writeSettings=x=>localStorage.setItem(KEY_SETTINGS,JSON.stringify(x));
  const ctx=()=>host.SillyTavern?.getContext?.()||{};
  const api=()=>host.TavernHelper||window.TavernHelper;
  function listChatPresets(pm){
    if(!pm||typeof pm.getPresetList!=='function')return [];
    try{const d=pm.getPresetList()||{},names=Object.keys(d.preset_names||{});if(names.length)return names;return Array.isArray(d.presets)?d.presets.map(p=>p?.name).filter(Boolean):[];}catch(e){console.warn('[异空间] 读取酒馆预设列表失败',e);return [];}
  }
  function validateStagePreset(readSettingsFn,getManagerFn){
    const s=(readSettingsFn||readSettings)();if(!s.stagePresetOn)return true;
    const name=String(s.stagePresetName||'').trim();if(!name)throw new Error('请先在异空间设置中选择小剧场专属预设');
    const pm=(getManagerFn||(()=>ctx().getPresetManager?.()))();if(!pm||typeof pm.findPreset!=='function'||typeof pm.selectPreset!=='function')throw new Error('当前酒馆 API 不支持读取或切换预设');
    if(pm.findPreset(name)==null||pm.findPreset(name)==='')throw new Error('当前 API 的预设列表里找不到「'+name+'」，请刷新预设列表后重新选择');
    const session=s.stagePresetSession;if(session&&String(pm.apiId||'current')!==session.apiId)throw new Error('小剧场启用期间酒馆 API 已改变；请先退出小剧场并恢复原预设，再重新进入');
    return true;
  }
  async function syncStagePreset(activeStage,readSettingsFn,writeSettingsFn,getManagerFn){
    const read=readSettingsFn||readSettings,write=writeSettingsFn||writeSettings,getManager=getManagerFn||((apiId)=>ctx().getPresetManager?.(apiId));
    const s=read(),session=s.stagePresetSession||null,enabled=!!activeStage&&s.stagePresetOn===true;
    if(enabled){
      const name=String(s.stagePresetName||'').trim();if(!name)throw new Error('请先在异空间设置中选择小剧场专属预设');
      const pm=getManager();if(!pm||typeof pm.findPreset!=='function'||typeof pm.selectPreset!=='function')throw new Error('当前酒馆 API 不支持读取或切换预设');
      const apiId=String(pm.apiId||'current'),value=pm.findPreset(name);if(value==null||value==='')throw new Error('当前 API 的预设列表里找不到「'+name+'」，请刷新预设列表后重新选择');
      const current=pm.getSelectedPresetName?.()||'';
      if(session&&session.apiId!==apiId)throw new Error('小剧场启用期间酒馆 API 已改变；请先退出小剧场并恢复原预设，再重新进入');
      const next=session?Object.assign({},session,{stageName:name,stageId:activeStage.id}):(current===name?null:{apiId,originalName:current,stageName:name,stageId:activeStage.id});
      if(current!==name)await pm.selectPreset(value);
      const v=Object.assign({},s,{stagePresetSession:next});write(v);return next;
    }
    if(!session)return null;
    const pm=getManager(session.apiId);if(!pm||typeof pm.findPreset!=='function'||typeof pm.selectPreset!=='function')throw new Error('找不到原 API 的预设管理器，暂时无法恢复酒馆原预设');
    const current=pm.getSelectedPresetName?.()||'';
    if(current===session.stageName){
      const value=pm.findPreset(session.originalName);if(value==null||value==='')throw new Error('找不到进入小剧场前的预设「'+session.originalName+'」，请手动恢复');
      await pm.selectPreset(value);
    }
    const v=Object.assign({},s,{stagePresetSession:null});write(v);return null;
  }
  const providers=[['openai','OpenAI'],['claude','Claude (Anthropic)'],['openrouter','OpenRouter'],['makersuite','Google MakerSuite'],['vertexai','Google Vertex AI'],['azure_openai','Azure OpenAI'],['custom','自定义兼容 API'],['deepseek','DeepSeek'],['xai','xAI (Grok)']];
  let editingStageId=null,activeTab='chats',stageView='list',settingsTab='prompts';
  let chatEdit=null,archiveEdit=null,stageTab='world',stageDraft=null,aiIdea='';
  const link={chats:new Set(),stages:new Set(),main:null,chatFiles:[],hidden:true,text:'',from:[],name:''};
  const INJ_STAGE='xspace_stage',INJ_MEM='xspace_memory',INJ_RULE='xspace_rule';
  function applyInjection(){
    try{updateFloat();}catch(e){console.warn(e);}
    const h=api(),prompts=[],rm=[],set=readSettings();
    const stage=readStages().find(s=>s.active);
    if(stage)prompts.push({id:INJ_STAGE,position:'in_chat',depth:1,role:'system',should_scan:false,content:'【当前小剧场设定·请优先遵循】\n《'+stage.title+'》\n'+stage.desc+(stage.summary?'\n\n【该小剧场的剧情记忆】\n'+stage.summary:'')});else rm.push(INJ_STAGE);
    if(stage&&set.stageRuleOn!==false&&(set.stageRulePrompt||'').trim())prompts.push({id:INJ_RULE,position:'in_chat',depth:0,role:'system',should_scan:false,content:set.stageRulePrompt.trim()+'\n\n（当前小剧场：《'+stage.title+'》）'});else rm.push(INJ_RULE);
    const meta=ctx().chatMetadata||{};
    if(meta.xspaceMemoryText)prompts.push({id:INJ_MEM,position:'in_chat',depth:1,role:'system',should_scan:false,content:'【记忆互通】以下是来自其他聊天/小剧场的剧情记忆，仅作背景参考，不要在回复中直接复述：\n'+meta.xspaceMemoryText});else rm.push(INJ_MEM);
    try{
      if(typeof h?.injectPrompts==='function'){
        if(rm.length&&typeof h.uninjectPrompts==='function')h.uninjectPrompts(rm);
        if(prompts.length)h.injectPrompts(prompts);
        return true;
      }
      const x=ctx();
      if(typeof x.setExtensionPrompt==='function'){
        prompts.forEach(p=>x.setExtensionPrompt(p.id,p.content,1,p.depth,false,0));
        rm.forEach(id=>x.setExtensionPrompt(id,'',1,1,false,0));
        return true;
      }
    }catch(e){console.warn('[异空间] 注入失败',e);}
    return false;
  }
  async function summarizeWith(instruction,text,generationId){
    const h=api();if(typeof h?.generate!=='function')throw new Error('酒馆助手 generate 接口不可用');
    const config={generation_id:generationId||newGenerationId('internal'),user_input:instruction+'\n\n'+text,should_silence:true,max_chat_history:0};
    const custom_api=settingsForRequest(readSettings());if(custom_api)config.custom_api=custom_api;
    const out=await h.generate(config);const result=typeof out==='string'?out:out?.content;
    if(!result?.trim())throw new Error('模型未返回内容');
    return result.trim();
  }
  function chunkLines(lines,limit){
    const chunks=[];let cur='';
    for(const l of lines){if(cur&&cur.length+l.length+1>limit){chunks.push(cur);cur='';}cur+=(cur?'\n':'')+l;}
    if(cur)chunks.push(cur);return chunks;
  }
  async function summarizeLines(lines,generationId,onProgress){
    const chunks=chunkLines(lines,10000),parts=[],s=readSettings();
    for(let i=0;i<chunks.length;i++){
      if(isBackgroundJobPaused(generationId))return '';
      if(onProgress)onProgress(chunks.length>1?'（第 '+(i+1)+'/'+chunks.length+' 段）':'');
      parts.push(await summarizeWith('请阅读以下聊天记录'+(chunks.length>1?'（第'+(i+1)+'/'+chunks.length+'段）':'')+'，写出简洁、准确的剧情摘要（约100-300字），保留人物关系、关键事件和未解决伏笔；只输出摘要。\n\n额外记忆总结要求：'+(s.memoryPrompt||''),chunks[i],generationId));
    }
    return parts.length===1?parts[0]:parts.join('\n\n');
  }
  async function summarizeChat(file,onProgress,generationId){
    const msgs=await readChatFile(file);
    const lines=msgs.filter(m=>link.hidden||!m.is_system).map(m=>(m.name||'未知')+': '+(m.mes||''));
    if(!lines.length)throw new Error('「'+file+'」没有可总结的内容');
    return summarizeLines(lines,generationId,onProgress);
  }
  const liveMessages=()=>{const c=ctx();return Array.isArray(c.chat)?c.chat.filter(x=>x&&typeof x==='object'&&('mes' in x)):[];};
  async function collectScopeLines(scope){
    const msgs=scope.file?await readChatFile(scope.file):liveMessages();
    if(!msgs.length)throw new Error(scope.file?'所选聊天文件没有消息':'当前酒馆聊天没有消息');
    let a=0,b=msgs.length-1;
    if(scope.mode==='last')a=Math.max(0,msgs.length-Math.max(1,scope.n));
    else if(scope.mode==='range'){a=Math.max(0,scope.from);b=Math.min(msgs.length-1,scope.to);}
    if(a>b)throw new Error('楼层范围无效（该聊天共 '+msgs.length+' 条，编号 0–'+(msgs.length-1)+'）');
    const lines=[];
    for(let i=a;i<=b;i++){const m=msgs[i];if(!scope.hidden&&m.is_system)continue;lines.push((m.name||'未知')+': '+(m.mes||''));}
    if(!lines.length)throw new Error('所选范围内没有可总结的内容');
    return {lines,a,b,total:msgs.length};
  }
  let lastScope={file:'',mode:'all',n:30,from:0,to:'',hidden:true};
  async function askScope(title){
    addStyle();ensureRoot();
    let files=[];try{files=await listChats();}catch{}
    const live=liveMessages().length,cur=curChatId();
    return new Promise(res=>{
      const panel=$('.xsh-panel'),mask=doc.createElement('div');mask.className='xsh-modal-mask';
      const opts=['<option value="">当前酒馆聊天（'+live+' 条）</option>'].concat(files.filter(f=>f.file!==cur).map(f=>'<option value="'+esc(f.file)+'"'+(lastScope.file===f.file?' selected':'')+'>'+esc(getChatInfo(f.file).title||f.file)+'（'+esc(f.count)+' 条）</option>')).join('');
      mask.innerHTML='<div class="xsh-modal xsh-scope"><b>'+esc(title)+'</b>'
        +'<label>读取来源<select class="xsh-select" data-f="file">'+opts+'</select></label>'
        +'<label>读取范围<select class="xsh-select" data-f="mode"><option value="all">全部楼层</option><option value="last">最近 N 条</option><option value="range">指定楼层范围</option></select></label>'
        +'<div data-box="last" style="display:none"><label>最近多少条<input class="xsh-input" type="number" min="1" data-f="n" value="'+lastScope.n+'"></label></div>'
        +'<div data-box="range" class="xsh-row" style="display:none"><label>起始楼层<input class="xsh-input" type="number" min="0" data-f="from" value="'+lastScope.from+'"></label><label>结束楼层（留空=到最后）<input class="xsh-input" type="number" min="0" data-f="to" value="'+esc(lastScope.to)+'"></label></div>'
        +'<div class="xsh-chat-meta">楼层编号与“楼层”页里的 # 编号一致，从 0 开始，首尾都包含。</div>'
        +'<label class="xsh-row"><span>包含被隐藏/系统楼层</span><input type="checkbox" data-f="hidden"></label>'
        +'<div class="xsh-modal-btns"><button class="xsh-btn primary" data-ok>开始总结</button><button class="xsh-btn" data-cancel>取消</button></div></div>';
      const q=s=>mask.querySelector(s),modeEl=q('[data-f="mode"]');
      modeEl.value=lastScope.mode;
