  function currentChatText(){
    const h=api();
    if(typeof h?.getChatMessages==='function'){
      const m=h.getChatMessages('0-{{lastMessageId}}');
      if(Array.isArray(m))return m.filter(x=>!x.is_hidden).map(x=>`${x.name||x.role||'未知'}: ${x.message||''}`).join('\n');
    }
    const c=ctx();
    if(Array.isArray(c.chat))return c.chat.map(x=>`${x.name||''}: ${x.mes||x.message||''}`).join('\n');
    throw new Error('无法读取当前聊天：缺少酒馆助手 getChatMessages 接口');
  }
