    const keyText=e=>{const k=Array.isArray(e.keys)?e.keys:(Array.isArray(e.key)?e.key:[]);return k.join(', ');};
    const norm=list.filter(e=>e&&e.uid!==undefined).map(e=>({uid:String(e.uid),comment:String(e.comment||keyText(e)||''),content:String(e.content||''),enabled:e.enabled!==undefined?!!e.enabled:!e.disable}));
