  async function buildStageContext(){
    const s=readSettings(),c=s.stageCtx||{},x=ctx(),out=[],stat={persona:false,char:false,entries:0};
    if(c.persona){
      const pu=x.powerUserSettings||{},pd=String(pu.persona_description||'').trim();
      if(pd){out.push('【user 人设：'+(x.name1||'User')+'】\n'+pd);stat.persona=true;}
    }
    if(c.char){
      const ch=Array.isArray(x.characters)?x.characters[x.characterId]:null;
      if(ch){
        const parts=[['描述',ch.description||ch.data?.description],['性格',ch.personality||ch.data?.personality],['场景',ch.scenario||ch.data?.scenario]].filter(p=>String(p[1]||'').trim()).map(p=>p[0]+'：'+String(p[1]).trim());
        if(parts.length){out.push('【char 人设：'+ch.name+'】\n'+parts.join('\n'));stat.char=true;}
      }
    }
    for(const [book,uids] of Object.entries(c.entries||{})){
      if(!Array.isArray(uids)||!uids.length)continue;
      const set=new Set(uids.map(String)),ents=await loadBookEntries(book);
