  function parseStageJson(text){
    const raw=text.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');
    const fallback=()=>{const lines=raw.split('\n').map(x=>x.trim()).filter(Boolean);return {title:lines[0]?.slice(0,40)||'新小剧场',subtitle:lines[1]?.slice(0,60)||'',desc:raw};};
    let obj;
    try{obj=JSON.parse(raw);}catch{const m=raw.match(/\{[\s\S]*\}/);if(!m)obj=fallback();else{try{obj=JSON.parse(m[0]);}catch{obj=fallback();}}}
    if(!obj||typeof obj!=='object')throw new Error('返回数据格式不正确');
    return {title:String(obj.title||obj.name||obj['标题']||'').trim(),subtitle:String(obj.subtitle||obj.sub_title||obj['描述']||'').trim(),desc:String(obj.desc||obj.worldview||obj.description||obj.content||obj.setting||obj['世界观描述']||obj['世界观']||'').trim()};
  }
  async function generateStageDraft(idea,generationId,cx){
    const s=readSettings(),h=api();
    if(!h||(typeof h.generate!=='function'&&typeof h.generateRaw!=='function'))throw new Error('酒馆助手 generate 接口不可用');
    const input=(s.stagePrompt||DEF.stagePrompt)+(cx&&cx.text?'\n\n【可参考的资料（仅供设计世界观时参考，不要逐字照搬）】\n'+cx.text:'')+'\n\n用户的创意：'+idea+'\n\n请只返回合法 JSON，不要 Markdown 代码块，格式为 {"title":"标题","subtitle":"一句话简介（30字内）","desc":"世界观描述，'+MIN_DESC+'-'+MAX_DESC+'字，包含开场情境"}。';
    const schema={name:'xspace_stage',description:'小剧场设定内容',strict:true,value:{type:'object',properties:{title:{type:'string'},subtitle:{type:'string'},desc:{type:'string'}},required:['title','subtitle','desc'],additionalProperties:false}};
    let customApi;
    if(s.stageApiMode==='custom'){if(!s.stageApiurl||!s.stageModel)throw new Error('请先在“设置 → 接口与其它”中填写独立小剧场 API 地址和模型');customApi={apiurl:s.stageApiurl.trim(),key:s.stageKey||'',model:s.stageModel,source:s.stageSource||'openai'};}
    else customApi=settingsForRequest(s);
    const call=(kind,withSchema)=>{
      const conf={generation_id:generationId||newGenerationId('stage'),should_silence:true};
      if(kind==='raw')conf.ordered_prompts=[{role:'user',content:input}];
      else{conf.user_input=input;conf.max_chat_history=0;conf.overrides={char_description:'',char_personality:'',scenario:'',world_info_before:'',world_info_after:'',persona_description:'',dialogue_examples:''};}
      if(withSchema)conf.json_schema=schema;
      if(customApi)conf.custom_api=customApi;
      return kind==='raw'?h.generateRaw(conf):h.generate(conf);
    };
    const schemaErr=/json.?schema|structured.?output|unsupported|not supported|response_format/i;
    const kinds=[typeof h.generateRaw==='function'?'raw':null,typeof h.generate==='function'?'gen':null].filter(Boolean);
    let out,err=null;
    for(const k of kinds){
      err=null;
      try{out=await call(k,true);}
      catch(e){
        if(isBackgroundJobPaused(generationId))throw e;
        err=e;
        if(schemaErr.test(String(e?.message||e))){try{out=await call(k,false);err=null;}catch(e2){if(isBackgroundJobPaused(generationId))throw e2;err=e2;}}
      }
      if(!err)break;
    }
    if(err)throw err;
    const text=(typeof out==='string'?out:out?.content||'').trim();
    if(!text)throw new Error('模型未返回内容');
    return parseStageJson(text);
  }
