      const v=readSettings();entries.forEach(({card,o,ta})=>{v[o.key]=ta.value.trim();if(o.onSave)o.onSave(card,v);});writeSettings(v);try{applyInjection();}catch{}
      entries.forEach(x=>{x.st.className='xsh-test-status success';x.st.textContent='已保存';});const status=toolbar.querySelector('[data-prompt-status]');status.className='xsh-test-status success';status.textContent='全部提示词已保存';
    };
  }
  function renderApiSettings(main){
    const s=readSettings(),sources=providers.map(([v,n])=>`<option value="${v}" ${s.source===v?'selected':''}>${n}</option>`).join(''),stageSources=providers.map(([v,n])=>`<option value="${v}" ${s.stageSource===v?'selected':''}>${n}</option>`).join('');
