    const sc=doc.createElement('div');sc.className='xsh-card';
    sc.innerHTML=`<b>小剧场生成 API</b><label>接口使用<select class="xsh-select" data-field="stage-api-mode"><option value="shared" ${s.stageApiMode==='shared'?'selected':''}>与记忆总结共用 API</option><option value="custom" ${s.stageApiMode==='custom'?'selected':''}>单独填写小剧场生成 API</option></select></label><div data-stage-api-fields style="display:${s.stageApiMode==='custom'?'block':'none'}"><label>API 类型<select class="xsh-select" data-field="stage-source">${stageSources}</select></label><label>API 地址<input class="xsh-input" data-field="stage-url" value="${esc(s.stageApiurl)}" placeholder="https://api.example.com/v1"></label><label>API 密钥<input class="xsh-input" type="password" data-field="stage-key" value="${esc(s.stageKey)}" autocomplete="off"></label><label>模型名称<input class="xsh-input" data-field="stage-model" value="${esc(s.stageModel)}" placeholder="填写模型名称"></label></div><button class="xsh-btn primary xsh-stage-edit-save" data-action="save-stage-api">保存</button><div class="xsh-test-status" data-prompt-status></div>`;
    main.append(sc);
    sc.querySelector('[data-field="stage-api-mode"]').onchange=e=>{sc.querySelector('[data-stage-api-fields]').style.display=e.target.value==='custom'?'block':'none';};
    sc.querySelector('[data-action="save-stage-api"]').onclick=()=>{const v=readSettings(),g=f=>sc.querySelector('[data-field="'+f+'"]'),st=sc.querySelector('[data-prompt-status]');v.stageApiMode=g('stage-api-mode').value;v.stageSource=g('stage-source').value;v.stageApiurl=g('stage-url').value.trim();v.stageKey=g('stage-key').value;v.stageModel=g('stage-model').value.trim();if(v.stageApiMode==='custom'&&(!v.stageApiurl||!v.stageModel)){st.className='xsh-test-status error';st.textContent='独立 API 需要填写地址和模型名称';return;}writeSettings(v);st.className='xsh-test-status success';st.textContent='保存成功';};
    const custom=$('#xsh-custom-settings'),tavernActions=$('#xsh-tavern-actions');
    $('#xsh-mode').onchange=()=>{const isCustom=$('#xsh-mode').value==='custom';custom.style.display=isCustom?'block':'none';tavernActions.style.display=isCustom?'none':'flex';$('#xsh-test-status').textContent='';};
    const collect=()=>Object.assign(readSettings(),{mode:$('#xsh-mode').value,source:$('#xsh-source').value,apiurl:$('#xsh-url').value.trim(),key:$('#xsh-key').value,model:$('#xsh-model').value||s.model});
    const saveSettings=()=>{const v=collect();if(v.mode==='custom'&&(!v.apiurl||!v.model)){setStatus('保存失败：请填写API地址并选择模型','error');return;}writeSettings(v);setStatus('设置已保存','success');};
    const setStatus=(text,state)=>{const el=$('#xsh-test-status');el.textContent=text;el.className=`xsh-test-status ${state||''}`.trim();};
    $('#xsh-models').onclick=async()=>{const b=$('#xsh-models');b.disabled=true;try{const v=collect();if(!v.apiurl)throw new Error('请先填写API地址');if(typeof api()?.getModelList!=='function')throw new Error('当前酒馆助手版本不支持 getModelList');const list=await api().getModelList({apiurl:v.apiurl,key:v.key});if(!Array.isArray(list)||!list.length)throw new Error('没有获取到模型');const sel=$('#xsh-model');sel.innerHTML=list.map(m=>`<option value="${esc(m)}">${esc(m)}</option>`).join('');if(list.includes(s.model))sel.value=s.model;setStatus(`模型列表获取成功：${list.length} 个模型`,'success');}catch(e){setStatus(`拉取模型失败：${e.message}`,'error');}finally{b.disabled=false;}};
