          if(typeof h.getModelList!=='function')throw new Error('当前酒馆助手版本不支持直接验证自定义 API 密钥；为避免误报，本次不判定连接成功');
          const models=await h.getModelList({apiurl:v.apiurl,key:v.key});
          if(!Array.isArray(models)||!models.length)throw new Error('自定义 API 未返回模型列表，无法验证接口地址和密钥');
        }
        const probe=`XSPACE_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,10)}`;
        const conf={user_input:`请只输出以下连接验证码，不要加引号或其他文字：${probe}`,should_silence:true,max_chat_history:0};
        if(v.mode==='custom')conf.custom_api={apiurl:v.apiurl,key:v.key,model:v.model,source:v.source};
        const out=await h.generate(conf),text=(typeof out==='string'?out:out?.content)?.trim();
        if(!text||!text.includes(probe))throw new Error('接口有返回，但没有匹配本次随机验证码；可能是错误信息或无效响应，未判定连接成功');
        setStatus(`连接成功：${v.mode==='custom'?'自定义 API 密钥校验及模型响应均通过':'酒馆当前 API 模型已响应'}`,'success');
      }catch(err){setStatus(`连接失败：${err?.message||String(err)}`,'error');}
