    };
    $('#xsh-test').onclick=testConnection;$('#xsh-test-custom').onclick=testConnection;
    const floatCard=doc.createElement('div');floatCard.className='xsh-card';floatCard.innerHTML='<b>正文浮标</b><span>如果浮标被拖到难以操作的位置，可恢复到屏幕右侧中部。</span><button class="xsh-btn" data-action="reset-float">恢复浮标位置</button>';main.append(floatCard);floatCard.querySelector('[data-action="reset-float"]').onclick=()=>{localStorage.removeItem(KEY_FLOAT);const f=$('#xspace-float');if(f){f.style.left='auto';f.style.right='12px';f.style.top='42%';}toast('浮标已恢复到屏幕右侧中部');};
    renderAutoCard(main);
    const noteCard=doc.createElement('div');noteCard.className='xsh-card';noteCard.innerHTML=`<div class="xsh-card"><b>接口说明</b><p>酒馆助手官方文档支持 generate() 用当前酒馆模型生成，也支持 generate({custom_api}) 使用兼容服务；getModelList({apiurl,key}) 可拉取模型列表。实际是否可用仍取决于你的酒馆助手版本、当前 API 与服务兼容性。</p></div>`;main.append(noteCard);
  }
  function attachIcon(){if($('#'+iconId))return true;const holder=$('#top-settings-holder');if(!holder)return false;const b=doc.createElement('div');b.id=iconId;b.className='drawer';b.innerHTML='<div class="drawer-toggle"><div class="drawer-icon fa-solid fa-star fa-fw" title="异空间"></div></div>';b.querySelector('.drawer-toggle').onclick=e=>{e.preventDefault();e.stopPropagation();openPanel('chats');};const anchor=$('#persona-management-button');if(anchor)anchor.before(b);else holder.append(b);return true;}
  const stops=[];
  try{if(typeof eventOn==='function'&&typeof tavern_events!=='undefined'){stops.push(eventOn(tavern_events.CHAT_CHANGED,onChatChanged));}else{const x=ctx();x.eventSource?.on?.(x.eventTypes?.CHAT_CHANGED||'chat_id_changed',onChatChanged);}}catch(e){console.warn('[异空间] 事件监听失败',e);}
  setTimeout(async()=>{lastChat={file:curChatId(),avatar:curChar()?.avatar||''};try{applyInjection();}catch(e){console.warn(e);}const stage=activeStageNow();if(stage&&readSettings().stagePresetOn)try{await syncStagePreset(stage);}catch(e){toast('小剧场专属预设初始化失败：'+e.message);}},1500);
  let tries=0;const timer=setInterval(()=>{if(placeEntry()||tries++>20)clearInterval(timer);},500);
