  let themeHook=0;const hookTries=setInterval(()=>{const sel=$('#themes');if(sel&&!sel.dataset.xshHook){sel.dataset.xshHook='1';sel.addEventListener('change',()=>setTimeout(()=>{try{applySkin();}catch{}},600));}if(sel||themeHook++>20)clearInterval(hookTries);},1000);
  window.addEventListener('pagehide',()=>{clearInterval(skinTimer);clearInterval(hookTries);$('#xspace-float')?.remove();stops.forEach(s=>{try{s?.stop?.();}catch{}});clearInterval(timer);$('#'+rootId)?.remove();$('#'+cssId)?.remove();$('#'+iconId)?.remove();$('#xsh-menu-entry')?.remove();$('#xsh-atm')?.remove();$('#xsh-skin')?.remove();$('#xsh-banner')?.remove();doc.body.removeAttribute('data-xsh-stage');});
